import re

class Manacher:
    PIPE_SEPARATOR = "|"
    ZERO_LENGTH = 0
    ONE = 1
    TWO = 2

    def __init__(self, input_string) -> None:
        self._input_string = input_string

    @property
    def input_string(self):
        return self._input_string

    @input_string.setter
    def input_string(self, value):
        self._input_string = value

    def _palindromic_length(self, center, diff, string):
        if (center - diff == -1 or center + diff == len(string)
                or string[center - diff] != string[center + diff]):
            return 0
        return self.ONE + self._palindromic_length(center, diff + self.ONE, string)

    def palindromic_length(self, center, diff, string):
        return self._palindromic_length(center, diff, string)

    def _build_transformed_string(self):
        transformed = ""
        for char in self._input_string[:-self.ONE]:
            transformed += char + self.PIPE_SEPARATOR
        transformed += self._input_string[-self.ONE]
        return transformed

    def _find_max_palindrome(self, transformed_string):
        max_length = self.ZERO_LENGTH
        start = self.ZERO_LENGTH

        for i in range(len(transformed_string)):
            length = self._palindromic_length(i, self.ONE, transformed_string)
            if max_length < length:
                max_length = length
                start = i

        return start, max_length

    def _extract_palindrome(self, transformed_string, start, max_length):
        extracted = ""
        for char in transformed_string[start - max_length:start + max_length + self.ONE]:
            if char != self.PIPE_SEPARATOR:
                extracted += char
        return extracted

    def palindromic_string(self):
        transformed_string = self._build_transformed_string()
        start, max_length = self._find_max_palindrome(transformed_string)
        return self._extract_palindrome(transformed_string, start, max_length)
